ALL_CAP = [(c[2], c[3]) for c in COUNTRIES]
ALL_CUR = [(c[4], c[5]) for c in COUNTRIES]
ALL_CTRY = [(c[0], c[1]) for c in COUNTRIES]

def pick3(pool, correct):
    cands = [x for x in pool if x[0] != correct[0]]
    rng.shuffle(cands)
    out = []
    for c in cands:
        if c[0] not in [o[0] for o in out]:
            out.append(c)
        if len(out) == 3:
            break
    return out

for (cn, cn_ne, cap, cap_ne, cur, cur_ne) in COUNTRIES:
    ds = pick3(ALL_CAP, (cap, cap_ne))
    em.emit(EX, 'Nepal Geography', 'World Geography', 'easy', 2,
            f'What is the capital of {cn}?',
            f'{cn_ne} को राजधानी कुन हो?',
            [cap] + [d[0] for d in ds], [cap_ne] + [d[1] for d in ds], 0,
            f'The capital of {cn} is {cap}.',
            f'{cn_ne} को राजधानी {cap_ne} हो।')
    ds = pick3(ALL_CUR, (cur, cur_ne))
    em.emit(EX, 'Nepal Geography', 'World Geography', 'medium', 2,
            f'What is the currency of {cn}?',
            f'{cn_ne} को मुद्रा के हो?',
            [cur] + [d[0] for d in ds], [cur_ne] + [d[1] for d in ds], 0,
            f'The currency of {cn} is the {cur}.',
            f'{cn_ne} को मुद्रा {cur_ne} हो।')
    ds = pick3(ALL_CTRY, (cn, cn_ne))
    em.emit(EX, 'Nepal Geography', 'World Geography', 'medium', 2,
            f'{cap} is the capital of which country?',
            f'{cap_ne} कुन देशको राजधानी हो?',
            [cn] + [d[0] for d in ds], [cn_ne] + [d[1] for d in ds], 0,
            f'{cap} is the capital of {cn}.',
            f'{cap_ne} {cn_ne} को राजधानी हो।')

